find the issue: #include "mbed.h"
#include <exception>

DigitalOut ledYellow(D2);
DigitalOut ledAmber(D3);
DigitalOut ledRed(D4);

Thread thread2;
Thread thread3;

int counter = 0;

// Subroutine for any LEDs
void ledAny (DigitalOut *ledA){
    while(true){
        *ledA = 1;
        ThisThread::sleep_for(500ms);
        *ledA =0;
        ThisThread::sleep_for(1500ms);
        printf("My pointer is %p\n", *ledA);
    }
}


// main() runs in its own thread in the OS
int main(){

    thread2.start(callback(ledAny, &ledYellow));
    ThisThread::sleep_for(1000ms);
    thread3.start(callback(ledAny, &ledAmber));

    while (true) {
        counter = counter + 1;

        ledRed.write(true);
        ThisThread::sleep_for(500ms);
        ledRed.write(false);
        ThisThread::sleep_for(500ms);

        if (counter>20){
            thread2.terminate();
        }


    }
}

output:
The problem turns out not to be in Mbed’s scheduler or Thread API at all, but in your printf:

    printf("My pointer is %p\n", *ledA);

Here you’ve used the “%p” format (which expects a pointer) but you are passing `*ledA` (i.e. you’ve dereferenced the pointer and are handing printf a `DigitalOut` object/value).  That mismatched call is undefined behaviour and will very often trash the stack.

You almost certainly meant either

  1) To actually print the pointer value:

     printf("My pointer is %p\n", (void *)ledA);

  2) Or, if you just wanted to inspect the pin’s state, print it as an integer:

     printf("My pin value is %d\n", ledA->read());

Once you fix that mismatch, the random crashes go away.

Below is a minimal “project” that

1. Defines your DB connection in one file  
2. Provides an HTML form to POST `field1` and `field2`  
3. Receives the POST, opens MySQL (`Bob`), and safely inserts the data  

PROJECT STRUCTURE  
— config.php  
— index.html  
— store.php  

--- config.php ---  
```php
<?php
// config.php
// your DB credentials:
define('DB_HOST', 'localhost');
define('DB_NAME', 'Bob');
define('DB_USER', 'your_db_username');
define('DB_PASS', 'your_db_password');
```

--- index.html ---  
```html
<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <title>Submit to Bob</title>
</head>
<body>
  <h1>Submit field1 & field2</h1>
  <form action="store.php" method="post">
    <label>Field1:
      <input type="text" name="field1" required>
    </label><br><br>
    <label>Field2:
      <input type="text" name="field2" required>
    </label><br><br>
    <button type="submit">Submit</button>
  </form>
</body>
</html>
```

--- store.php ---  
```php
<?php
// store.php
require 'config.php';

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    exit('Method Not Allowed');
}

// grab & trim input
$field1 = isset($_POST['field1']) ? trim($_POST['field1']) : '';
$field2 = isset($_POST['field2']) ? trim($_POST['field2']) : '';

if ($field1 === '' || $field2 === '') {
    http_response_code(400);
    exit('Both fields are required.');
}

try {
    // connect via PDO
    $pdo = new PDO(
      "mysql:host=" . DB_HOST . ";dbname=" . DB_NAME . ";charset=utf8mb4",
      DB_USER,
      DB_PASS,
      [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]
    );

    // prepare & execute
    $stmt = $pdo->prepare(
      "INSERT INTO bob_table (field1, field2) VALUES (:field1, :field2)"
    );
    $stmt->execute([
      ':field1' => $field1,
      ':field2' => $field2
    ]);

    echo "Success! ID of inserted row: " . $pdo->lastInsertId();
} catch (PDOException $e) {
    http_response_code(500);
    echo "Database error: " . htmlspecialchars($e->getMessage());
}
```

--- SQL to create the table ---  
Run this once (e.g. via phpMyAdmin or the MySQL CLI) to prepare your `Bob` database:

```sql
CREATE TABLE IF NOT EXISTS bob_table (
  id INT AUTO_INCREMENT PRIMARY KEY,
  field1 VARCHAR(255) NOT NULL,
  field2 VARCHAR(255) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
```

DEPLOYMENT  
1. Place `config.php`, `index.html` and `store.php` in your web-root (or a subfolder).  
2. Edit `config.php` with your real MySQL hostname, username and password.  
3. Ensure the database `Bob` exists and you’ve run the `CREATE TABLE` above.  
4. Point your browser to `index.html`, fill the form, and click Submit.  

That’s it—your PHP app opens MySQL, receives `field1` & `field2` via POST, and stores them safely.

Below is a minimal Chrome Manifest V3 extension that adds a toolbar button. When clicked it grabs the current page’s HTML and downloads it as “<page-title>.html”.

1) Create a new folder, e.g. “save‐page”.
2) Inside it, create these two files:

— manifest.json —  
```json
{
  "manifest_version": 3,
  "name": "Save Page Content",
  "version": "1.0",
  "description": "Download the current page’s HTML",
  "permissions": [
    "downloads",
    "scripting",
    "activeTab"
  ],
  "background": {
    "service_worker": "background.js"
  },
  "action": {
    "default_title": "Save Page"
  }
}
```

— background.js —  
```js
// background service worker
chrome.action.onClicked.addListener(async (tab) => {
  if (!tab.id) return;

  // inject code into the page to grab its HTML
  const [injectionResult] = await chrome.scripting.executeScript({
    target: { tabId: tab.id },
    func: () => {
      // serialize the <html> element
      return document.documentElement.outerHTML;
    }
  });

  const html = injectionResult.result;
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);

  // derive a safe filename from the page title
  let filename = (tab.title || "page").replace(/[\\\/:*?"<>|]/g, "_");
  if (!filename.toLowerCase().endsWith(".html")) {
    filename += ".html";
  }

  chrome.downloads.download({
    url,
    filename
  }, () => {
    // revoke the blob when done
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });
});
```

3) Load the extension in Chrome:
- Open chrome://extensions  
- Enable “Developer mode” (top right)  
- Click “Load unpacked” and select your “save‐page” folder.

Now click the toolbar icon on any page; the HTML will be saved via the Downloads folder.

instruction:
Write functionality to print the rxdataF variable in c:
ru->common.rxdataF     = (int32_t**)malloc16(ru->nb_rx*sizeof(int32_t*) );
ru->common.rxdataF[i] = (int32_t*)malloc16_clear(sizeof(int32_t)*(NUMBER_RX_BUFFERS*fp->symbols_per_slot*fp->ofdm_symbol_size) );

output:
Below is a simple C helper that will walk through every antenna, every OFDM‐symbol and sub‐carrier (for all RX buffers) and print out the contents of `rxdataF[ant][idx]`.  We assume that each `int32_t` is actually a 16b‐real/16b‐imag complex sample (packed as 0xRRRRIIII), but you can of course comment‐out the unpacking and just print the raw 32‐bit word if you prefer.

```c
#include <stdio.h>
#include <stdint.h>

/*
  ru->nb_rx            number of RX antennas
  ru->common.rxdataF   int32_t **  array [nb_rx][NUMBER_RX_BUFFERS*symbols_per_slot*ofdm_symbol_size]
  fp->symbols_per_slot number of OFDM symbols per slot
  fp->ofdm_symbol_size number of subcarriers per OFDM symbol
  NUMBER_RX_BUFFERS    number of RX buffers
*/

void print_rxdataF(int nb_rx,
                   int32_t **rxdataF,
                   int number_rx_buffers,
                   int symbols_per_slot,
                   int ofdm_symbol_size) {
  int samples_per_buffer = symbols_per_slot * ofdm_symbol_size;
  int total_samples     = number_rx_buffers * samples_per_buffer;

  for (int ant = 0; ant < nb_rx; ant++) {
    printf("=== Antenna %d ===\n", ant);
    for (int buf = 0; buf < number_rx_buffers; buf++) {
      printf("  -- Buffer %d --\n", buf);
      for (int sym = 0; sym < symbols_per_slot; sym++) {
        printf("    Symbol %2d :\n", sym);
        for (int sc = 0; sc < ofdm_symbol_size; sc++) {
          int idx = buf * samples_per_buffer
                    + sym * ofdm_symbol_size
                    + sc;
          int32_t w = rxdataF[ant][idx];

          /* unpack 16b real / 16b imag */
          int16_t real = (int16_t)(w >> 16);
          int16_t imag = (int16_t)(w & 0xFFFF);

          printf("      sc %3d : raw=0x%08X  ->  re=%6d  im=%6d\n",
                 sc, (unsigned)w, real, imag);
        }
      }
    }
  }
}

/* example of how you might call it: */
void foo(RU_t *ru, frame_parms_t *fp) {
  print_rxdataF(
    ru->nb_rx,
    ru->common.rxdataF,
    NUMBER_RX_BUFFERS,
    fp->symbols_per_slot,
    fp->ofdm_symbol_size
  );
}
```

If you don’t want to unpack into real/imag you can simply do:

```c
printf("    idx=%5d  raw=0x%08X (%d)\n",
       idx, (unsigned)w, (int)w);
```

instead of the 16‐bit unpacking above.

