Here’s a minimal C example that shows a blocking read() on stdin being interrupted by a signal (SIGALRM), returning –1 with errno == EINTR, and how you can transparently retry the read:

```c
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>

/* Simple handler to catch SIGALRM. Does nothing but interrupt the system call. */
static void alarm_handler(int signo) {
    (void)signo;
}

/*
 * safe_read:
 *   A small wrapper around read() that restarts the call if it was
 *   interrupted by a signal (errno == EINTR).
 *   Returns the number of bytes read, 0 on EOF, or –1 on other errors.
 */
ssize_t safe_read(int fd, void *buf, size_t count) {
    ssize_t n;
    do {
        n = read(fd, buf, count);
    } while (n < 0 && errno == EINTR);
    return n;
}

int main(void) {
    char  buffer[128];
    ssize_t n;

    /* Install our simple handler for SIGALRM */
    struct sigaction sa = {0};
    sa.sa_handler = alarm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;       /* don’t specify SA_RESTART, so read() will fail with EINTR */
    if (sigaction(SIGALRM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    /* Arrange for SIGALRM in 5 seconds to force-read to be interrupted */
    alarm(5);

    printf("Please type something within 5 seconds:\n");

    /* This read will block until data arrives or SIGALRM fires */
    n = safe_read(STDIN_FILENO, buffer, sizeof(buffer));

    if (n < 0) {
        /* real error */
        perror("read");
    }
    else if (n == 0) {
        /* EOF */
        printf("EOF on stdin\n");
    }
    else {
        /* Successfully read n bytes */
        write(STDOUT_FILENO, buffer, n);
        printf("\n(Read %zd bytes)\n", n);
    }

    return 0;
}
```

How it works:

1. We set up a signal handler for `SIGALRM` without `SA_RESTART`.  
2. We call `alarm(5)`, so in 5 seconds `SIGALRM` will be delivered.  
3. We invoke `safe_read()`, which loops on `read()`:  
   – If `read()` returns ≥0, we return that (bytes read or 0 = EOF).  
   – If `read()` returns –1 and `errno == EINTR`, we know a signal interrupted the syscall; we simply retry.  
   – If `read()` returns –1 for any other `errno`, we propagate the error.  

You can remove the wrapper and do the retry inline:

```c
ssize_t n;
do {
    n = read(fd, buf, len);
} while (n < 0 && errno == EINTR);

if (n < 0) {
    perror("read");
    /* handle error */
}
```

This is the classic pattern for handling `EINTR` on blocking I/O calls.

Below are two minimal C++ examples showing how to bind to port 888 and read whatever data is sent to you—one for UDP (“datagrams”) and one for TCP (stream). Pick the one that fits your needs (or adapt both).

UDP Server Example (receives “packets” via recvfrom):

```cpp
// udp_server.cpp
#include <iostream>
#include <cstring>
#include <cstdlib>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

int main() {
    // 1) create UDP socket
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }

    // allow reuse of address
    int opt = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(sock);
        return EXIT_FAILURE;
    }

    // 2) bind to port 888 on all interfaces
    sockaddr_in servaddr;
    std::memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;  // 0.0.0.0
    servaddr.sin_port = htons(888);

    if (bind(sock, (sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        perror("bind");
        close(sock);
        return EXIT_FAILURE;
    }

    std::cout << "Listening for UDP packets on port 888...\n";

    // 3) loop and recvfrom()
    while (true) {
        char buffer[1500];
        sockaddr_in cliaddr;
        socklen_t len = sizeof(cliaddr);
        ssize_t n = recvfrom(sock, buffer, sizeof(buffer)-1, 0,
                             (sockaddr*)&cliaddr, &len);
        if (n < 0) {
            perror("recvfrom");
            break;
        }
        buffer[n] = '\0';
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &cliaddr.sin_addr, client_ip, sizeof(client_ip));
        std::cout << "Received " << n
                  << " bytes from " << client_ip
                  << ":" << ntohs(cliaddr.sin_port)
                  << "  Data: " << buffer << "\n";
    }

    close(sock);
    return 0;
}
```

Compile and run:
```
g++ udp_server.cpp -o udp_server
./udp_server
```

TCP Server Example (accepts connections on port 888 and reads a stream):

```cpp
// tcp_server.cpp
#include <iostream>
#include <cstring>
#include <cstdlib>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

int main() {
    // 1) create TCP socket
    int listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_fd < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }

    // allow reuse of address
    int opt = 1;
    if (setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(listen_fd);
        return EXIT_FAILURE;
    }

    // 2) bind to port 888
    sockaddr_in servaddr;
    std::memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;
    servaddr.sin_port = htons(888);

    if (bind(listen_fd, (sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        perror("bind");
        close(listen_fd);
        return EXIT_FAILURE;
    }

    // 3) listen
    if (listen(listen_fd, 10) < 0) {
        perror("listen");
        close(listen_fd);
        return EXIT_FAILURE;
    }
    std::cout << "TCP server listening on port 888...\n";

    while (true) {
        // 4) accept a new connection
        sockaddr_in cliaddr;
        socklen_t clilen = sizeof(cliaddr);
        int conn_fd = accept(listen_fd, (sockaddr*)&cliaddr, &clilen);
        if (conn_fd < 0) {
            perror("accept");
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &cliaddr.sin_addr, client_ip, sizeof(client_ip));
        std::cout << "Client connected: " << client_ip 
                  << ":" << ntohs(cliaddr.sin_port) << "\n";

        // 5) read data
        char buf[1024];
        ssize_t n;
        while ((n = read(conn_fd, buf, sizeof(buf)-1)) > 0) {
            buf[n] = '\0';
            std::cout << "Read " << n << " bytes: " << buf << "\n";
        }
        if (n < 0) perror("read");

        std::cout << "Client disconnected: " << client_ip << "\n";
        close(conn_fd);
    }

    close(listen_fd);
    return 0;
}
```

Compile and run:
```
g++ tcp_server.cpp -o tcp_server
./tcp_server
```

Choose UDP if you expect discrete packets (e.g. sensors, syslog, DNS-like), TCP if you need a reliable byte-stream. If you really meant “sniff all IP packets on port 888” (as a network‐sniffer), you’d need a raw socket (AF_PACKET or AF_INET+IPPROTO_TCP/UDP) and root privileges. Let me know if you need that!

Here’s a “pure-expression” solution that you can paste into the Path property of a Shape Layer.  It will draw a 500×500 square centered on the layer’s anchor point, with only the top-right corner rounded to radius r:

```js
// corner radius
r = 50;

// overall size
size = 500;
h = size/2;

// “kappa” for approximating a circle with Béziers
k = 0.5522847498;

// clamp radius so we don’t over-round
r = Math.min(r, h);
kr = k * r;

// define the five vertices (in order)
// 0 = top-left, 1 = just before the corner on top edge,
// 2 = just after the corner on right edge,
// 3 = bottom-right, 4 = bottom-left
v = [
  [-h,   -h],
  [ h-r, -h],
  [ h,   -h+r],
  [ h,    h],
  [-h,    h]
];

// in-tangents for each vertex
inT = [
  [0,   0],
  [0,   0],
  [0,  kr],
  [0,   0],
  [0,   0]
];

// out-tangents for each vertex
outT = [
  [0,   0],
  [kr,  0],
  [0,   0],
  [0,   0],
  [0,   0]
];

// build and return the closed path
createPath(v, inT, outT, true);
```

Explanation:

• We split the top edge just before the corner (at x = +h–r) and the right edge just after it (y = –h+r).  
• Between those two points we place a quarter-circle arc via Bézier handles of length k × r.  
• All other corners remain sharp (their in- and out-tangents are [0,0]).

Below is a self‐contained example in C# that demonstrates one way to merge two Word documents with the OpenXML SDK.  It

1. Creates a brand‐new document  
2. Copies the **styles**, **theme** and **font table** (so you keep the look of doc1)  
3. Extracts only the **first two “pages”** of doc1 (we iterate until we see two page‐breaks or section‐breaks)  
4. Copies **headers** and **footers** from doc1  
5. Copies **body** paragraphs/tables (only) from doc2  
6. Copies the **glossary** part from doc2  
7. Re‐maps any image parts referenced in either source  

Because OpenXML doesn’t really _know_ about “pages” (that’s a layout concern of Word), we simply watch for explicit `<w:br w:type="page"/>` or section‐breaks (`<w:sectPr>`), count two of them, and stop copying.  If your documents don’t use explicit breaks, you’ll have to adapt to your own pagination scheme (bookmarks, etc.).

```csharp
using System;
using System.IO;
using System.Linq;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;
using DocumentFormat.OpenXml.Drawing.Wordprocessing;
using A = DocumentFormat.OpenXml.Drawing;

public static class OpenXmlMerger
{
  /// <summary>
  /// Merge two Word documents into one.
  /// From doc1: take only first two pages, all headers, footers, styles, theme and fonts.
  /// From doc2: take only body content (no headers/footers) and the glossary part.
  /// All images are re-mapped into the new document.
  /// </summary>
  public static void MergeDocuments(
    string sourceFile1,
    string sourceFile2,
    string outputFile)
  {
    // Open sources read-only
    using (var doc1 = WordprocessingDocument.Open(sourceFile1, false))
    using (var doc2 = WordprocessingDocument.Open(sourceFile2, false))
    {
      // Create new document
      using (var newDoc = WordprocessingDocument.Create(
               outputFile, WordprocessingDocumentType.Document))
      {
        var newMain = newDoc.AddMainDocumentPart();
        newMain.Document = new Document(new Body());

        // 1) Copy styles/theme/fontTable/numbering from doc1
        CopyPartIfExists(doc1.MainDocumentPart, 
                         p => p.StyleDefinitionsPart, 
                         newMain, 
                         (src, dest) => dest.FeedData(src.GetStream()));
        CopyPartIfExists(doc1.MainDocumentPart, 
                         p => p.ThemePart, 
                         newMain, 
                         (src, dest) => dest.FeedData(src.GetStream()));
        CopyPartIfExists(doc1.MainDocumentPart, 
                         p => p.FontTablePart, 
                         newMain, 
                         (src, dest) => dest.FeedData(src.GetStream()));
        CopyPartIfExists(doc1.MainDocumentPart, 
                         p => p.NumberingDefinitionsPart, 
                         newMain, 
                         (src, dest) => dest.FeedData(src.GetStream()));

        // 2) Copy headers and footers from doc1
        foreach (var hdr in doc1.MainDocumentPart.HeaderParts)
        {
          var nh = newMain.AddNewPart<HeaderPart>();
          nh.FeedData(hdr.GetStream());
          // Note: We'll need to map the relationship IDs in the sectPr below.
        }
        foreach (var ftr in doc1.MainDocumentPart.FooterParts)
        {
          var nf = newMain.AddNewPart<FooterPart>();
          nf.FeedData(ftr.GetStream());
        }

        // 3) Extract first two pages of doc1 body
        CopyFirstNPages(
          sourceBody: doc1.MainDocumentPart.Document.Body,
          newBody: newMain.Document.Body,
          sourceMainPart: doc1.MainDocumentPart,
          targetMainPart: newMain,
          maxPages: 2);

        // 4) Now append doc2 body content (all paragraphs/tables but skip sectPr)
        foreach (var el in doc2.MainDocumentPart.Document.Body.Elements()
                           .Where(e => !(e is SectionProperties)))
        {
          var clone = el.CloneNode(true);
          RemapImageParts(clone, doc2.MainDocumentPart, newMain);
          newMain.Document.Body.Append(clone);
        }

        // 5) Copy glossary part from doc2
        if (doc2.MainDocumentPart.GlossaryDocumentPart != null)
        {
          var srcGloss = doc2.MainDocumentPart.GlossaryDocumentPart;
          var tgtGloss = newMain.AddNewPart<GlossaryDocumentPart>();
          tgtGloss.FeedData(srcGloss.GetStream());

          // remap images inside glossary
          foreach (var img in srcGloss.ImageParts)
          {
            var newImg = tgtGloss.AddImagePart(img.ContentType);
            newImg.FeedData(img.GetStream());
          }
        }

        // 6) Save and finish
        newMain.Document.Save();
      }
    }
  }

  /// <summary>
  /// Copies up to N “pages” worth of elements from sourceBody
  /// to newBody by counting explicit page-breaks and section-breaks.
  /// </summary>
  private static void CopyFirstNPages(
    Body sourceBody,
    Body newBody,
    MainDocumentPart sourceMainPart,
    MainDocumentPart targetMainPart,
    int maxPages)
  {
    int pageCount = 1;
    foreach (var el in sourceBody.Elements())
    {
      // stop if we already hit maxPages
      if (pageCount > maxPages)
        break;

      // detect a page break inside a paragraph
      bool foundBreak = el
        .Descendants<Break>()
        .Any(br => br.Type != null && br.Type == BreakValues.Page);

      // detect a section break
      if (el is SectionProperties)
        foundBreak = true;

      // clone & remap images
      var clone = el.CloneNode(true);
      RemapImageParts(clone, sourceMainPart, targetMainPart);
      newBody.Append(clone);

      if (foundBreak)
        pageCount++;
    }

    // Copy the final SectionProperties from doc1 (to preserve header/footer links)
    var lastSect = sourceBody
      .Elements<SectionProperties>()
      .LastOrDefault();
    if (lastSect != null)
    {
      // remap header/footer refs if needed
      newBody.Append(lastSect.CloneNode(true));
    }
  }

  /// <summary>
  /// Find any drawing/blip image references in 'element',
  /// copy the image parts from sourceMain to targetMain,
  /// and update the r:embed IDs in the cloned element.
  /// </summary>
  private static void RemapImageParts(
    OpenXmlElement element,
    MainDocumentPart sourceMain,
    MainDocumentPart targetMain)
  {
    // There are a few shapes where images live;
    // one common is the <a:blip> inside <wp:inline> or <w:drawing>
    foreach (var blip in element.Descendants<A.Blip>())
    {
      var embed = blip.Embed?.Value;
      if (String.IsNullOrEmpty(embed))
        continue;

      var imgPart = (ImagePart)sourceMain.GetPartById(embed);
      if (imgPart == null)
        continue;

      var newImg = targetMain.AddImagePart(imgPart.ContentType);
      using (var src = imgPart.GetStream())
      using (var dst = newImg.GetStream(FileMode.Create))
        src.CopyTo(dst);

      // assign new rel id
      blip.Embed.Value = targetMain.GetIdOfPart(newImg);
    }
  }

  /// <summary>
  /// Utility: if sourcePartPartSelector(source) != null, copy it into target.
  /// </summary>
  private static void CopyPartIfExists<T>(
    MainDocumentPart source,
    Func<MainDocumentPart, T> sourcePartSelector,
    MainDocumentPart target,
    Action<T, T> feedData)
    where T : OpenXmlPart
  {
    var srcPart = sourcePartSelector(source);
    if (srcPart == null)
      return;

    var destPart = target.AddNewPart<T>();
    feedData(srcPart, destPart);

    // Also copy over any image parts in that part
    foreach (var img in srcPart.ImageParts)
    {
      var tImg = destPart.AddImagePart(img.ContentType);
      using (var s = img.GetStream())
      using (var d = tImg.GetStream(FileMode.Create))
        s.CopyTo(d);
    }
  }
}
```

Usage example:

```csharp
OpenXmlMerger.MergeDocuments(
   @"C:\temp\FirstDoc.docx",
   @"C:\temp\SecondDoc.docx",
   @"C:\temp\MergedResult.docx");
```

Notes:

- This code presumes your first document actually has explicit page‐breaks or section‐breaks after page 1 and page 2.  
- If you rely purely on Word’s layout (no breaks) you’ll need a more advanced pagination approach (for example, inserting your own bookmarks or using the Word Interop to count pages).  
- We do a fairly shallow remapping of images; if you have charts, embedded OLE objects or other exotic parts you’d have to extend the same pattern.  
- We copy numbering from doc1 but _do not_ merge numbering definitions from doc2.  If your second document has lists you wish to preserve, you’d apply a similar `CopyPartIfExists` on its `NumberingDefinitionsPart` (and possibly remap number IDs).

