Below is one possible implementation. We keep all “business‐logic” about where to store / fetch favorites in a single `FavoritesManager` and expose three methods: `all()`, `add($name)` and `remove($name)`.  A controller then just delegates to it and returns JSON.

---

1. FavoritesManager

```php
<?php
namespace App\Favorites;

use Illuminate\Support\Facades\Session;
use App\Models\User;
use App\Models\Favorite;

class FavoritesManager
{
    const SESSION_KEY = 'favorites';

    /** @var User|null */
    protected $user;

    /**
     * @param User|null $user  Inject the current user or null for guests
     */
    public function __construct(?User $user = null)
    {
        $this->user = $user;
    }

    /**
     * @return bool
     */
    protected function isGuest(): bool
    {
        return $this->user === null;
    }

    /**
     * Get the current favorites as an array of names.
     *
     * @return string[]
     */
    public function all(): array
    {
        if ($this->isGuest()) {
            return Session::get(self::SESSION_KEY, []);
        }

        // Eager‐loaded or live fetch from DB
        return $this->user
                    ->favorites()
                    ->pluck('name')
                    ->toArray();
    }

    /**
     * Add a name to favorites.
     *
     * @param  string  $name
     * @return bool    true if added, false if already existed
     */
    public function add(string $name): bool
    {
        if ($this->isGuest()) {
            $fav = Session::get(self::SESSION_KEY, []);
            if (in_array($name, $fav, true)) {
                return false;
            }
            $fav[] = $name;
            Session::put(self::SESSION_KEY, $fav);
            return true;
        }

        // logged‐in user
        $exists = $this->user
                       ->favorites()
                       ->where('name', $name)
                       ->exists();
        if ($exists) {
            return false;
        }

        // assumes Favorite has fillable ['name']
        $this->user->favorites()->create(['name' => $name]);
        return true;
    }

    /**
     * Remove a name from favorites.
     *
     * @param  string  $name
     * @return bool    true if removed, false if it wasn't in the list
     */
    public function remove(string $name): bool
    {
        if ($this->isGuest()) {
            $fav = Session::get(self::SESSION_KEY, []);
            // filter out
            $filtered = array_values(array_filter(
                $fav, 
                fn($item) => $item !== $name
            ));
            if (count($filtered) === count($fav)) {
                // nothing removed
                return false;
            }
            Session::put(self::SESSION_KEY, $filtered);
            return true;
        }

        // logged‐in user
        $model = $this->user
                      ->favorites()
                      ->where('name', $name)
                      ->first();
        if (! $model) {
            return false;
        }
        $model->delete();
        return true;
    }
}
```

Notes:

- We store guest favorites in the session under the key `favorites`.  
- For a logged‐in user we assume a standard one‐to‐many:  
  in `User` model:
  ```php
  public function favorites()
  {
      return $this->hasMany(\App\Models\Favorite::class);
  }
  ```
- Your `Favorite` model/migration should have at least `id`, `user_id` & `name` columns.

---

2. FavoritesController

```php
<?php
namespace App\Http\Controllers;

use App\Favorites\FavoritesManager;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;

class FavoritesController extends Controller
{
    /**
     * Return the list of favorites (for guest or user).
     */
    public function index(Request $request)
    {
        $manager = new FavoritesManager(Auth::user());
        $favorites = $manager->all();
        return response()->json($favorites);
    }

    /**
     * Add a favorite.
     * Expects JSON body { "name": "Some Business" }
     */
    public function store(Request $request)
    {
        $data = $request->validate([
            'name' => 'required|string|max:255',
        ]);

        $manager = new FavoritesManager(Auth::user());
        $added = $manager->add($data['name']);

        if (! $added) {
            return response()->json([
                'message' => 'Already in favorites',
            ], 409);
        }

        return response()->json(['message' => 'Added'], 201);
    }

    /**
     * Remove a favorite.
     * Expects JSON body { "name": "Some Business" }
     */
    public function destroy(Request $request)
    {
        $data = $request->validate([
            'name' => 'required|string|max:255',
        ]);

        $manager = new FavoritesManager(Auth::user());
        $removed = $manager->remove($data['name']);

        if (! $removed) {
            return response()->json([
                'message' => 'Not found in favorites',
            ], 404);
        }

        return response()->json(['message' => 'Removed'], 200);
    }
}
```

3. Routes (in `routes/api.php` or `routes/web.php` if you prefer; for an SPA API you’d often use `api.php`):

```php
use App\Http\Controllers\FavoritesController;

Route::get('/favorites',    [FavoritesController::class, 'index']);
Route::post('/favorites',   [FavoritesController::class, 'store']);
Route::delete('/favorites', [FavoritesController::class, 'destroy']);
```

With this in place your Vue/Inertia front‐end can call:

- GET `/favorites` → array of names
- POST `/favorites` `{name}` → add
- DELETE `/favorites` `{name}` → remove

And `FavoritesManager` will transparently switch between session (guest) and DB (logged‐in).

