Below is an example of an ERC-1155 “Creds” contract that you can use as a starting point.  It supports:

1. Multiple “credential” token IDs in a single contract  
2. Role-based minting/revocation (using OpenZeppelin’s AccessControl)  
3. Optional soul-bound (non-transferable) credentials  
4. Per-user expiry timestamps for credentials  
5. Simple “isValid” helper  

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/token/ERC1155/extensions/ERC1155Supply.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract Creds1155 is ERC1155, ERC1155Supply, AccessControl {
    bytes32 public constant ADMIN_ROLE  = keccak256("ADMIN_ROLE");
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    // If a credential tokenId is soulbound, it cannot be transferred
    mapping(uint256 => bool) public soulbound;

    // credentialExpiry[tokenId][account] = unix timestamp
    mapping(uint256 => mapping(address => uint256)) public credentialExpiry;

    event CredentialMinted(address indexed to, uint256 indexed id, uint256 expiry);
    event CredentialRevoked(address indexed from, uint256 indexed id);

    constructor(string memory uri_) ERC1155(uri_) {
        // Grant admin to deployer
        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _setupRole(ADMIN_ROLE, msg.sender);

        // By default ADMIN can mint
        _setRoleAdmin(MINTER_ROLE, ADMIN_ROLE);
        grantRole(MINTER_ROLE, msg.sender);
    }

    /// @notice Set whether a tokenId should be soul-bound
    function setSoulbound(uint256 id, bool isBound) external onlyRole(ADMIN_ROLE) {
        soulbound[id] = isBound;
    }

    /// @notice Mint a credential token to `to` with optional expiry
    /// @param to address receiving the cred
    /// @param id tokenId of the credential
    /// @param expiry unix timestamp after which cred is invalid (0 = no expiry)
    function mintCredential(
        address to,
        uint256 id,
        uint256 expiry
    ) external onlyRole(MINTER_ROLE) {
        require(to != address(0), "Creds1155: mint to zero");
        // we mint exactly 1 token per cred (soulbound use-case)
        _mint(to, id, 1, "");
        _setExpiry(to, id, expiry);
        emit CredentialMinted(to, id, expiry);
    }

    /// @notice Batch mint
    function mintCredentialsBatch(
        address to,
        uint256[] calldata ids,
        uint256[] calldata expiries
    ) external onlyRole(MINTER_ROLE) {
        require(ids.length == expiries.length, "Length mismatch");
        uint256[] memory amounts = new uint256[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            amounts[i] = 1;
        }
        _mintBatch(to, ids, amounts, "");

        for (uint256 i = 0; i < ids.length; i++) {
            _setExpiry(to, ids[i], expiries[i]);
            emit CredentialMinted(to, ids[i], expiries[i]);
        }
    }

    /// @notice Revoke a credential (burns it regardless of expiry)
    function revokeCredential(address from, uint256 id) external onlyRole(MINTER_ROLE) {
        require(balanceOf(from, id) > 0, "No cred to revoke");
        _burn(from, id, 1);
        delete credentialExpiry[id][from];
        emit CredentialRevoked(from, id);
    }

    /// @notice Check if `account` has a non-expired credential `id`
    function isValid(address account, uint256 id) public view returns (bool) {
        if (balanceOf(account, id) == 0) return false;
        uint256 exp = credentialExpiry[id][account];
        return exp == 0 || block.timestamp <= exp;
    }

    /// @dev Internal helper to set the expiry mapping
    function _setExpiry(address account, uint256 id, uint256 expiry) internal {
        if (expiry > 0) {
            require(expiry > block.timestamp, "Expiry in past");
        }
        credentialExpiry[id][account] = expiry;
    }

    // Override transfers to enforce soul-bound tokens
    function safeTransferFrom(
        address from,
        address to,
        uint256 id,
        uint256 amount,
        bytes memory data
    ) public virtual override {
        require(!soulbound[id], "Creds1155: soulbound");
        super.safeTransferFrom(from, to, id, amount, data);
    }

    function safeBatchTransferFrom(
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) public virtual override {
        for (uint256 i = 0; i < ids.length; i++) {
            require(!soulbound[ids[i]], "Creds1155: soulbound");
        }
        super.safeBatchTransferFrom(from, to, ids, amounts, data);
    }

    // The following functions are overrides required by Solidity.
    function _beforeTokenTransfer(
        address operator,
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) internal virtual override(ERC1155, ERC1155Supply) {
        super._beforeTokenTransfer(operator, from, to, ids, amounts, data);
    }
}
```

How it works  
1) ADMIN_ROLE can assign MINTER_ROLE, toggle soul-binding per tokenId, etc.  
2) MINTER_ROLE can issue credentials via `mintCredential` (with optional expiry) or revoke them.  
3) `isValid(user, id)` returns true only if the user holds the token and it’s not expired.  
4) If you mark a tokenId as soulbound, any transfer attempts will revert.  

You can extend this further by:  
- Emitting richer events (e.g. RoleGranted, RoleRevoked are already in AccessControl)  
- Adding on-chain metadata per credential (URI per tokenId)  
- Integrating with a front end to visualize user creds.

Below is a minimal, self-contained TCP “stack” in TypeScript. It will let you:

1. Parse a raw IPv4‐payload (i.e. a TCP segment) from a Uint8Array into a nice object  
2. Build a TCP segment (with options, checksum, etc.) into a Uint8Array  
3. A very simple Connection class that implements the SYN–SYN/ACK–ACK handshake, sequence‐number tracking, ACKing, and clean close  

It does ​not​ implement congestion control, timeouts & retransmits, fast‐start, sliding‐windows beyond basic, out‐of‐order buffers, etc. but should give you a solid starting point.

---  
1) A TCP header parser / builder (including pseudo‐header checksum)  
```ts
// types.ts
export interface TCPSegment {
  srcPort:       number;
  dstPort:       number;
  seqNum:        number;
  ackNum:        number;
  dataOffset:    number;      // in 32-bit words
  flags:         { ns:boolean; cwr:boolean; ece:boolean; urg:boolean; ack:boolean; psh:boolean; rst:boolean; syn:boolean; fin:boolean };
  windowSize:    number;
  checksum:      number;
  urgentPointer: number;
  options?:      Uint8Array; // raw options bytes (if any)
  payload?:      Uint8Array; // application‐payload
}
```

```ts
// tcp.ts
import { TCPSegment } from './types';

function readUInt16(buf:Uint8Array, off:number):number {
  return (buf[off]<<8)|buf[off+1];
}
function readUInt32(buf:Uint8Array, off:number):number {
  return (buf[off]<<24)|(buf[off+1]<<16)|(buf[off+2]<<8)|buf[off+3];
}
function writeUInt16(buf:Uint8Array, off:number, v:number){
  buf[off]=v>>>8; buf[off+1]=v&0xff;
}
function writeUInt32(buf:Uint8Array, off:number, v:number){
  buf[off]=v>>>24; buf[off+1]=(v>>>16)&0xff; buf[off+2]=(v>>>8)&0xff; buf[off+3]=v&0xff;
}

// Compute the TCP checksum including IPv4 pseudo‐header
export function tcpChecksum(
  srcIp:string, dstIp:string,
  segment:Uint8Array
):number {
  // build pseudo‐header
  const ps = new Uint8Array(12+segment.length + (segment.length%2));
  const dv = new DataView(ps.buffer);
  function ipToBytes(ip:string, off:number){
    ip.split('.').forEach((b,i)=>ps[off+i]=parseInt(b,10)&0xff);
  }
  ipToBytes(srcIp,0);
  ipToBytes(dstIp,4);
  ps[8] = 0;
  ps[9] = 6;             // protocol = TCP
  writeUInt16(ps,10, segment.length);
  ps.set(segment,12);
  // if odd length, last byte is already zero
  let sum=0;
  for(let i=0;i<ps.length;i+=2){
    sum += (ps[i]<<8)|ps[i+1];
    while(sum>0xffff) sum = (sum & 0xffff) + (sum>>>16);
  }
  return (~sum)&0xffff;
}

// Parse a raw TCP segment from ip‐payload
export function parseTCPSegment(
  payload:Uint8Array
):TCPSegment {
  if(payload.length<20) throw new Error("TCP header too short");
  const seg:TCPSegment = {
    srcPort:       readUInt16(payload,0),
    dstPort:       readUInt16(payload,2),
    seqNum:        readUInt32(payload,4)>>>0,
    ackNum:        readUInt32(payload,8)>>>0,
    dataOffset:    payload[12]>>>4,
    flags:         { ns:false, cwr:false, ece:false, urg:false, ack:false, psh:false, rst:false, syn:false, fin:false },
    windowSize:    readUInt16(payload,14),
    checksum:      readUInt16(payload,16),
    urgentPointer: readUInt16(payload,18),
    options:       undefined,
    payload:       undefined
  };
  // decode flags
  const fl = ((payload[12]&0x1)<<8)|(payload[13]&0xff);
  seg.flags = {
    ns:  !!(fl & 0x100),
    cwr: !!(fl & 0x80),
    ece: !!(fl & 0x40),
    urg: !!(fl & 0x20),
    ack: !!(fl & 0x10),
    psh: !!(fl & 0x08),
    rst: !!(fl & 0x04),
    syn: !!(fl & 0x02),
    fin: !!(fl & 0x01),
  };
  const hdrBytes = seg.dataOffset * 4;
  if(hdrBytes>20) {
    seg.options = payload.subarray(20, hdrBytes);
  }
  if(payload.length>hdrBytes){
    seg.payload = payload.subarray(hdrBytes);
  }
  return seg;
}

// Build a TCP segment given your fields + src/dst IP for checksum
export function buildTCPSegment(
  seg:TCPSegment,
  srcIp:string,
  dstIp:string
):Uint8Array {
  const opts = seg.options || new Uint8Array(0);
  const pay = seg.payload || new Uint8Array(0);
  // dataOffset is in 32‐bit words
  const dataOffset = 5 + Math.ceil(opts.length/4);
  const buf = new Uint8Array(dataOffset*4 + pay.length);
  writeUInt16(buf, 0, seg.srcPort);
  writeUInt16(buf, 2, seg.dstPort);
  writeUInt32(buf, 4, seg.seqNum);
  writeUInt32(buf, 8, seg.ackNum);
  buf[12] = (dataOffset<<4) | ((seg.flags.ns?1:0)&0x1);
  let flagBits = 0;
  if(seg.flags.cwr) flagBits |= 0x80;
  if(seg.flags.ece) flagBits |= 0x40;
  if(seg.flags.urg) flagBits |= 0x20;
  if(seg.flags.ack) flagBits |= 0x10;
  if(seg.flags.psh) flagBits |= 0x08;
  if(seg.flags.rst) flagBits |= 0x04;
  if(seg.flags.syn) flagBits |= 0x02;
  if(seg.flags.fin) flagBits |= 0x01;
  buf[13] = flagBits;
  writeUInt16(buf,14, seg.windowSize);
  writeUInt16(buf,16, 0);            // checksum placeholder
  writeUInt16(buf,18, seg.urgentPointer);
  if(opts.length) buf.set(opts,20);
  if(pay.length)  buf.set(pay, dataOffset*4);
  // compute checksum
  const sum = tcpChecksum(srcIp,dstIp, buf);
  writeUInt16(buf,16, sum);
  return buf;
}
