2) A tiny TCP connection state machine  
```ts
// connection.ts
import { TCPSegment } from './types';
import { parseTCPSegment, buildTCPSegment } from './tcp';

type TCPState =
  | 'CLOSED'|'LISTEN'
  | 'SYN_SENT'|'SYN_RECEIVED'
  | 'ESTABLISHED'
  | 'FIN_WAIT_1'|'FIN_WAIT_2'|'CLOSE_WAIT'|'LAST_ACK'|'TIME_WAIT';

export interface TCPOptions {
  srcIp: string;
  dstIp: string;
  srcPort: number;
  dstPort: number;
  onSegmentOut(data:Uint8Array):void; // implementer must send this over raw IPv4
  onEstablished?():void;
  onData?(payload:Uint8Array):void;
  onClose?():void;
}

export class TCPConnection {
  private state: TCPState = 'CLOSED';
  private snd_una=0, snd_nxt=0, snd_wnd=65535;
  private rcv_nxt=0, rcv_wnd=65535;
  private iss=0;  // initial send seq
  private irs=0;  // initial recv seq

  constructor(private o:TCPOptions){
    this.iss = Math.floor(Math.random()*0xffffffff);
  }

  // client side connect()
  connect(){
    if(this.state!=='CLOSED') throw Error("not closed");
    this.state='SYN_SENT';
    this.snd_nxt = this.iss;
    // SYN, no data
    const seg:TCPSegment = {
      srcPort: this.o.srcPort,
      dstPort: this.o.dstPort,
      seqNum:  this.snd_nxt,
      ackNum:  0,
      dataOffset:5,
      flags: {ns:false,cwr:false,ece:false,urg:false,ack:false,psh:false,rst:false,syn:true,fin:false},
      windowSize:this.rcv_wnd,
      urgentPointer:0
    };
    const pkt = buildTCPSegment(seg,this.o.srcIp,this.o.dstIp);
    this.o.onSegmentOut(pkt);
    this.snd_nxt++;
  }

  // server side listen()
  listen(){
    if(this.state!=='CLOSED') throw Error("not closed");
    this.state='LISTEN';
  }

  // incoming raw IPv4 payload
  receive(raw:Uint8Array){
    const seg = parseTCPSegment(raw);
    // quick port check
    if(seg.dstPort!==this.o.srcPort || seg.srcPort!==this.o.dstPort) return;
    switch(this.state){
    case 'LISTEN':
      if(seg.flags.syn){
        this.irs = seg.seqNum;
        this.rcv_nxt = seg.seqNum+1;
        this.state='SYN_RECEIVED';
        // send SYN/ACK
        const synack:TCPSegment = {
          srcPort:this.o.srcPort, dstPort:this.o.dstPort,
          seqNum:this.iss, ackNum:this.rcv_nxt,
          dataOffset:5,
          flags:{ns:false,cwr:false,ece:false,urg:false,ack:true,psh:false,rst:false,syn:true,fin:false},
          windowSize:this.rcv_wnd, urgentPointer:0
        };
        this.snd_una=this.iss;
        this.snd_nxt=this.iss+1;
        this.o.onSegmentOut(buildTCPSegment(synack,this.o.srcIp,this.o.dstIp));
      }
      break;
    case 'SYN_SENT':
      if(seg.flags.syn && seg.flags.ack && seg.ackNum===this.snd_nxt){
        this.irs=seg.seqNum;
        this.rcv_nxt=seg.seqNum+1;
        this.snd_una=seg.ackNum;
        // send ACK
        this.state='ESTABLISHED';
        const ack:TCPSegment = {
          srcPort:this.o.srcPort,dstPort:this.o.dstPort,
          seqNum:this.snd_nxt, ackNum:this.rcv_nxt,
          dataOffset:5,
          flags:{ns:false,cwr:false,ece:false,urg:false,ack:true,psh:false,rst:false,syn:false,fin:false},
          windowSize:this.rcv_wnd, urgentPointer:0
        };
        this.o.onSegmentOut(buildTCPSegment(ack,this.o.srcIp,this.o.dstIp));
        this.o.onEstablished?.();
      }
      break;
    case 'SYN_RECEIVED':
      if(seg.flags.ack && seg.ackNum===this.snd_nxt){
        this.state='ESTABLISHED';
        this.snd_una=seg.ackNum;
        this.o.onEstablished?.();
      }
      break;
    case 'ESTABLISHED':
      // handle data
      if(seg.flags.fin){
        this.state='CLOSE_WAIT';
        this.rcv_nxt = seg.seqNum+1;
        // ACK the FIN
        const ackFin:TCPSegment = {
          srcPort:this.o.srcPort,dstPort:this.o.dstPort,
          seqNum:this.snd_nxt, ackNum:this.rcv_nxt,
          dataOffset:5,
          flags:{ns:false,cwr:false,ece:false,urg:false,ack:true,psh:false,rst:false,syn:false,fin:false},
          windowSize:this.rcv_wnd, urgentPointer:0
        };
        this.o.onSegmentOut(buildTCPSegment(ackFin,this.o.srcIp,this.o.dstIp));
        this.o.onClose?.();
      }
      if(seg.payload && seg.payload.length){
        // deliver and ACK
        this.o.onData?.(seg.payload);
        this.rcv_nxt += seg.payload.length;
        const ackData:TCPSegment = {
          srcPort:this.o.srcPort,dstPort:this.o.dstPort,
          seqNum:this.snd_nxt, ackNum:this.rcv_nxt,
          dataOffset:5,
          flags:{ns:false,cwr:false,ece:false,urg:false,ack:true,psh:false,rst:false,syn:false,fin:false},
          windowSize:this.rcv_wnd, urgentPointer:0
        };
        this.o.onSegmentOut(buildTCPSegment(ackData,this.o.srcIp,this.o.dstIp));
      }
      break;
    case 'CLOSE_WAIT':
      // ignore further
      break;
    default:
      // for brevity, other states omitted
      break;
    }
  }

  // application calls send() to push data (only in ESTABLISHED)
  send(data:Uint8Array){
    if(this.state!=='ESTABLISHED') throw Error("not established");
    const seg:TCPSegment = {
      srcPort:this.o.srcPort,dstPort:this.o.dstPort,
      seqNum:this.snd_nxt, ackNum:this.rcv_nxt,
      dataOffset:5,
      flags:{ns:false,cwr:false,ece:false,urg:false,ack:true,psh:true,rst:false,syn:false,fin:false},
      windowSize:this.rcv_wnd, urgentPointer:0,
      payload:data
    };
    const pkt = buildTCPSegment(seg,this.o.srcIp,this.o.dstIp);
    this.o.onSegmentOut(pkt);
    this.snd_nxt += data.length;
  }

  // application calls close()
  close(){
    if(this.state!=='ESTABLISHED') throw Error("invalid state to close");
    this.state='FIN_WAIT_1';
    const fin:TCPSegment = {
      srcPort:this.o.srcPort,dstPort:this.o.dstPort,
      seqNum:this.snd_nxt, ackNum:this.rcv_nxt,
      dataOffset:5,
      flags:{ns:false,cwr:false,ece:false,urg:false,ack:true,psh:false,rst:false,syn:false,fin:true},
      windowSize:this.rcv_wnd, urgentPointer:0
    };
    this.o.onSegmentOut(buildTCPSegment(fin,this.o.srcIp,this.o.dstIp));
    this.snd_nxt++;
  }
}
```

