```php
namespace App\Scim;

use Psr\Http\Message\ResponseInterface;

class Response
{
  public static function json(ResponseInterface $resp, array $body, int $status=200): ResponseInterface
  {
    $resp->getBody()->write(json_encode($body, JSON_UNESCAPED_SLASHES));
    return $resp
      ->withHeader('Content-Type','application/scim+json')
      ->withStatus($status);
  }

  public static function error(ResponseInterface $resp, string $detail, int $status=400): ResponseInterface
  {
    $body = [
