Below is a self‐contained Vitis HLS example for a LeNet-5 style CNN that does MNIST inference.  It uses a single 28×28 input image and produces a 10-way softmax output.  All weights/biases are shown as placeholders—you’ll want to replace them with your trained values (e.g. obtained from Python/TensorFlow/PyTorch).  Pragmas are added to pipeline and partition arrays so that it can be synthesized efficiently.

```cpp
// lenet_hls.cpp
#include <cmath>
#include <ap_fixed.h>

//
// Tunable fixed-point type.  Change to float if you prefer.
//
typedef ap_fixed<16,6> data_t;

// Dimensions for LeNet-5:
//
//  Input:       1×28×28
//  Conv1:       6×(1×5×5)   → 6×24×24
//  Pool1:       6×12×12
//  Conv2:      16×(6×5×5)   → 16×8×8
//  Pool2:      16×4×4
//  FC1:           120 nodes
//  FC2:            84 nodes
//  FC3:            10 nodes (softmax)
//

//
// Placeholder weight & bias arrays.
// You must fill these with your trained parameters!
//
static const data_t conv1_w[6][1][5][5] = { /* … */ };
static const data_t conv1_b[6]           = { /* … */ };

static const data_t conv2_w[16][6][5][5] = { /* … */ };
static const data_t conv2_b[16]          = { /* … */ };

static const data_t fc1_w[120][16*4*4]   = { /* … */ };
static const data_t fc1_b[120]           = { /* … */ };

static const data_t fc2_w[84][120]       = { /* … */ };
static const data_t fc2_b[84]            = { /* … */ };

static const data_t fc3_w[10][84]        = { /* … */ };
static const data_t fc3_b[10]            = { /* … */ };

//
// Top-level function for Vitis HLS
//
extern "C" {
void lenet_hls(
    const data_t input[28][28],  // AXI master-port reads
    data_t       output[10]      // AXI master-port writes
) {
#pragma HLS INTERFACE m_axi     port=input  offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi     port=output offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=input  bundle=control
#pragma HLS INTERFACE s_axilite port=output bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    //
    // Buffers for intermediate feature maps
    //
    static data_t feat1[6][24][24];
    static data_t pool1[6][12][12];
    static data_t feat2[16][8][8];
    static data_t pool2[16][4][4];
#pragma HLS ARRAY_PARTITION variable=feat1  complete dim=1
#pragma HLS ARRAY_PARTITION variable=pool1  complete dim=1
#pragma HLS ARRAY_PARTITION variable=feat2  complete dim=1
#pragma HLS ARRAY_PARTITION variable=pool2  complete dim=1

    //
    // 1) CONV1 + ReLU
    //
    for(int m=0; m<6; m++) {
      for(int i=0; i<24; i++) {
        for(int j=0; j<24; j++) {
#pragma HLS PIPELINE
          data_t acc = conv1_b[m];
          for(int c=0; c<1; c++) {
            for(int ki=0; ki<5; ki++) {
              for(int kj=0; kj<5; kj++) {
                acc += input[i+ki][j+kj] * conv1_w[m][c][ki][kj];
              }
            }
          }
          // ReLU
          feat1[m][i][j] = (acc < 0) ? 0 : acc;
        }
      }
    }

    //
    // 2) POOL1 (2×2 max)
    //
    for(int m=0; m<6; m++) {
      for(int i=0; i<12; i++) {
        for(int j=0; j<12; j++) {
#pragma HLS PIPELINE
          data_t a = feat1[m][2*i  ][2*j  ];
          data_t b = feat1[m][2*i+1][2*j  ];
          data_t c = feat1[m][2*i  ][2*j+1];
          data_t d = feat1[m][2*i+1][2*j+1];
          data_t m1 = (a>b)?a:b;
          data_t m2 = (c>d)?c:d;
          pool1[m][i][j] = (m1>m2)?m1:m2;
        }
      }
    }

    //
    // 3) CONV2 + ReLU
    //
    for(int m=0; m<16; m++) {
      for(int i=0; i<8; i++) {
        for(int j=0; j<8; j++) {
#pragma HLS PIPELINE
          data_t acc = conv2_b[m];
          for(int c=0; c<6; c++) {
            for(int ki=0; ki<5; ki++) {
              for(int kj=0; kj<5; kj++) {
                acc += pool1[c][i+ki][j+kj] * conv2_w[m][c][ki][kj];
              }
            }
          }
          feat2[m][i][j] = (acc < 0) ? 0 : acc;
        }
      }
    }

    //
    // 4) POOL2 (2×2 max)
    //
    for(int m=0; m<16; m++) {
      for(int i=0; i<4; i++) {
        for(int j=0; j<4; j++) {
#pragma HLS PIPELINE
          data_t a = feat2[m][2*i  ][2*j  ];
          data_t b = feat2[m][2*i+1][2*j  ];
          data_t c = feat2[m][2*i  ][2*j+1];
          data_t d = feat2[m][2*i+1][2*j+1];
          data_t m1 = (a>b)?a:b;
          data_t m2 = (c>d)?c:d;
          pool2[m][i][j] = (m1>m2)?m1:m2;
        }
      }
    }

    //
    // Flatten for FC layers:
    //  size = 16×4×4 = 256
    //
    data_t flat[16*4*4];
#pragma HLS ARRAY_PARTITION variable=flat complete dim=1

    for(int m=0; m<16; m++) {
      for(int i=0; i<4; i++) {
        for(int j=0; j<4; j++) {
          int idx = m*16 + i*4 + j;
          flat[idx] = pool2[m][i][j];
        }
      }
    }

    //
    // 5) FC1 (256 → 120) + ReLU
    //
    data_t fc1_out[120];
#pragma HLS ARRAY_PARTITION variable=fc1_out complete dim=1
    for(int o=0; o<120; o++) {
#pragma HLS PIPELINE
      data_t acc = fc1_b[o];
      for(int i=0; i<16*4*4; i++) {
        acc += flat[i] * fc1_w[o][i];
      }
      fc1_out[o] = (acc < 0) ? 0 : acc;
    }

    //
    // 6) FC2 (120 → 84) + ReLU
    //
    data_t fc2_out[84];
#pragma HLS ARRAY_PARTITION variable=fc2_out complete dim=1
    for(int o=0; o<84; o++) {
#pragma HLS PIPELINE
      data_t acc = fc2_b[o];
      for(int i=0; i<120; i++) {
        acc += fc1_out[i] * fc2_w[o][i];
      }
      fc2_out[o] = (acc < 0) ? 0 : acc;
    }

    //
    // 7) FC3 (84 → 10) → logits
    //
    data_t logits[10];
#pragma HLS ARRAY_PARTITION variable=logits complete dim=1
    for(int o=0; o<10; o++) {
#pragma HLS PIPELINE
      data_t acc = fc3_b[o];
      for(int i=0; i<84; i++) {
        acc += fc2_out[i] * fc3_w[o][i];
      }
      logits[o] = acc;
    }

    //
    // 8) Softmax
    //
    data_t maxv = logits[0];
    for(int i=1; i<10; i++) if(logits[i] > maxv) maxv = logits[i];

    data_t sum = 0;
    for(int i=0; i<10; i++) {
      sum += hls::exp(logits[i] - maxv);
    }

    for(int i=0; i<10; i++) {
      output[i] = hls::exp(logits[i] - maxv) / sum;
    }
}
} // extern "C"
```

How to use:

1.  Replace all the `/* … */` in the weight/bias definitions with your trained parameters.  
2.  Run Vitis HLS:  
    ```
    vitis_hls
    open_project lenet_proj
    add_files lenet_hls.cpp
    csynth_design
    csim_design        # to run C‐simulation
    cosim_design       # to run RTL‐co‐simulation
    synth_design       # to generate the IP
    ```
3.  Export the IP and integrate into your SDAccel/Vitis accelerator design.

Notes:

•   This implementation uses `data_t=ap_fixed<16,6>`.  Feel free to switch to `float` or other fixed-point sizes depending on your accuracy/performance tradeoff.  
•   All loops in the per‐element operations are pipelined; the arrays for channels and flattened vectors are fully partitioned so that every multiply/add can operate in parallel.  
•   If resource usage is too high, you can relax the `ARRAY_PARTITION` directives to block/reshape partitioning, or reduce precision.

