— editor.js —
```javascript
// Simple Sprite Editor

//---------------------
// Sprite Class
//---------------------
class Sprite {
  constructor(img, x, y) {
    this.img = img;
    this.x = x;
    this.y = y;
    this.w = img.width;
    this.h = img.height;
    this.rot = 0;          // degrees
    this.id = Sprite._nextId++;
  }
}
Sprite._nextId = 1;

//---------------------
// Globals & State
//---------------------
const canvas = document.getElementById('canvas');
const ctx    = canvas.getContext('2d');
let sprites = [];
let selected = null;
let dragOffset = { x:0, y:0 };
let isDragging = false;
let currentImage = null;

//---------------------
// UI References
//---------------------
const fileInput  = document.getElementById('fileInput');
const addBtn     = document.getElementById('addBtn');
const propId     = document.getElementById('propId');
const propX      = document.getElementById('propX');
const propY      = document.getElementById('propY');
const propW      = document.getElementById('propW');
const propH      = document.getElementById('propH');
const propR      = document.getElementById('propR');
const delBtn     = document.getElementById('delBtn');
const exportBtn  = document.getElementById('exportBtn');
const importBtn  = document.getElementById('importBtn');
const jsonOut    = document.getElementById('jsonOutput');
const jsonIn     = document.getElementById('jsonInput');

//---------------------
// Helpers
//---------------------
function toRadians(d) { return d * Math.PI/180 }
function drawAll() {
  ctx.clearRect(0,0,canvas.width,canvas.height);
  sprites.forEach(sp => {
    ctx.save();
    // translate to sprite center
    ctx.translate(sp.x + sp.w/2, sp.y + sp.h/2);
    ctx.rotate(toRadians(sp.rot));
    ctx.drawImage(sp.img, -sp.w/2, -sp.h/2, sp.w, sp.h);
    if (sp === selected) {
      // draw bounding box
      ctx.strokeStyle = 'red';
      ctx.lineWidth = 2;
      ctx.strokeRect(-sp.w/2, -sp.h/2, sp.w, sp.h);
    }
    ctx.restore();
  });
}

function isPointInSprite(sp, px,py) {
  // convert point to sprite local coords:
  let cx = sp.x + sp.w/2, cy = sp.y + sp.h/2;
  let dx = px - cx, dy = py - cy;
  let r = toRadians(-sp.rot);
  let lx = dx * Math.cos(r) - dy * Math.sin(r);
  let ly = dx * Math.sin(r) + dy * Math.cos(r);
  return lx >= -sp.w/2 && lx <= sp.w/2 && ly >= -sp.h/2 && ly <= sp.h/2;
}

function selectSprite(sp) {
  selected = sp;
  if (!sp) {
    propId.textContent = '—';
    [propX,propY,propW,propH,propR].forEach(i => i.value = '');
    delBtn.disabled = true;
  } else {
    propId.textContent = sp.id;
    propX.value = Math.round(sp.x);
    propY.value = Math.round(sp.y);
    propW.value = Math.round(sp.w);
    propH.value = Math.round(sp.h);
    propR.value = Math.round(sp.rot);
    delBtn.disabled = false;
  }
  drawAll();
}

//---------------------
// Mouse Events
//---------------------
canvas.addEventListener('mousedown', e => {
  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left, my = e.clientY - rect.top;
  // find topmost sprite under pointer
  for (let i = sprites.length-1; i>=0; i--) {
    if (isPointInSprite(sprites[i], mx, my)) {
      selectSprite(sprites[i]);
      isDragging = true;
      dragOffset.x = mx - selected.x;
      dragOffset.y = my - selected.y;
      return;
    }
  }
  // no sprite clicked: deselect
  selectSprite(null);
});

canvas.addEventListener('mousemove', e => {
  if (!isDragging || !selected) return;
  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left, my = e.clientY - rect.top;
  selected.x = mx - dragOffset.x;
  selected.y = my - dragOffset.y;
  // update props
  propX.value = Math.round(selected.x);
  propY.value = Math.round(selected.y);
  drawAll();
});

canvas.addEventListener('mouseup', e => {
  isDragging = false;
});

//---------------------
// File Loader & Add
//---------------------
fileInput.addEventListener('change', ev => {
  const file = ev.target.files[0];
  if (!file) return;
  const img = new Image();
  img.onload = () => {
    currentImage = img;
    addBtn.disabled = false;
  };
  img.src = URL.createObjectURL(file);
});

addBtn.addEventListener('click', () => {
  if (!currentImage) return;
  const sp = new Sprite(currentImage, 50, 50);
  sprites.push(sp);
  selectSprite(sp);
  drawAll();
});

//---------------------
// Property Inputs
//---------------------
function updateProp(key, parser=Number) {
  if (!selected) return;
  selected[key] = parser(event.target.value);
  drawAll();
}
propX.addEventListener('input', () => updateProp('x'));
propY.addEventListener('input', () => updateProp('y'));
propW.addEventListener('input', () => updateProp('w'));
propH.addEventListener('input', () => updateProp('h'));
propR.addEventListener('input', () => updateProp('rot'));

//---------------------
// Delete
//---------------------
delBtn.addEventListener('click', () => {
  if (!selected) return;
  sprites = sprites.filter(s=>s!==selected);
  selectSprite(null);
  drawAll();
});

//---------------------
// Export / Import JSON
//---------------------
exportBtn.addEventListener('click', () => {
  const data = sprites.map(s => ({
    id: s.id, x:s.x, y:s.y, w:s.w, h:s.h, rot:s.rot,
    src: s.img.src  // assumes data URL or same-origin
  }));
  jsonOut.value = JSON.stringify(data, null,2);
});

importBtn.addEventListener('click', () => {
  let data;
  try { data = JSON.parse(jsonIn.value); }
  catch(e){ alert("Invalid JSON"); return; }
  sprites = [];
  selected = null;
  Sprite._nextId = 1;
  // load each sprite in turn:
  let loaded = 0;
  data.forEach(item => {
    const img = new Image();
    img.onload = () => {
      const sp = new Sprite(img, item.x, item.y);
      sp.w = item.w; sp.h = item.h; sp.rot = item.rot; sp.id = item.id;
      sprites.push(sp);
      loaded++;
      if (loaded === data.length) {
        drawAll();
      }
    };
    img.src = item.src;
  });
});

// initial draw
drawAll();
```

How it works in brief:

1. Load an image file → keeps it in `currentImage`.  
2. “Add Sprite” → instantiates a new Sprite at (50,50).  
3. Click on a sprite to select it (highlighted in red). Drag it with the mouse.  
4. Edit X,Y,W,H,Rot in the sidebar to fine‐tune.  
5. “Delete Sprite” removes it.  
6. “Export JSON” serializes all sprites (including each image’s `src` URL) into the textarea.  
7. “Import JSON” parses that JSON, reloads each image, and rebuilds the scene.  

Feel free to extend—for example adding resize‐handles, layer reordering buttons, snapping, better hit‐testing, etc.

Below is one possible implementation of a very‐generic, data‐driven Action system.  You feed it a JSON/YAML/dict config that describes a sequence of “steps” (damage, heal, etc.), each of which has:

  * an “action” type (e.g. damage or heal)  
  * a “target” field (actor or target)  
  * an “amount” field: a small expression in terms of `actor`, `target`, any extra `config` parameters you pass in, and even the value of the previous step (`last`)  

At runtime we evaluate those expressions in a very limited, local namespace (no builtins), apply them in order, and keep track of the last value.  This scales to arbitrary new steps (burn, shield, buff, etc.) simply by adding new action names and writing small handler methods.

```python
# character.py
class Character:
    def __init__(self, char_data):
        self.name   = char_data["name"]
        self.hp     = char_data["hp"]
        self.damage = char_data["damage"]
    def __repr__(self):
        return f"<Character {self.name} hp={self.hp} dmg={self.damage}>"

# action.py
import ast, operator

class Action:
    """
    A data‐driven sequence of steps.  Each step must be a dict:
       {
         "action": "damage"|"heal"|...,
         "target": "actor"|"target",
         "amount":  "<py expression using actor, target, config, last>"
       }
    """
    def __init__(self, cfg: dict):
        self.name  = cfg.get("name", "<unnamed>")
        self.steps = cfg["steps"]

    def execute(self, actor: Character, target: Character, **config):
        # Build the eval namespace
        ctx = {
            "actor": actor,
            "target": target,
            "config": config
        }
        last = None
        for step in self.steps:
            amt = self._safe_eval(step["amount"], ctx, last)
            who = actor if step.get("target","target")=="actor" else target

            if step["action"] == "damage":
                who.hp -= amt
            elif step["action"] == "heal":
                who.hp += amt
            else:
                raise RuntimeError(f"Unknown action '{step['action']}'")

            last = amt

        return

    def _safe_eval(self, expr: str, ctx: dict, last):
        """
        Evaluate a simple arithmetic expression using only our ctx + last.
        No builtins, no attribute setting, no imports.
        """
        local = dict(ctx)
        if last is not None:
            local["last"] = last

        # parse the expression into an AST
        tree = ast.parse(expr, mode="eval")

        # walk the AST and reject dangerous nodes
        for node in ast.walk(tree):
            if isinstance(node, (ast.Call, ast.Import, ast.ImportFrom, ast.Attribute)):
                raise ValueError("Unsafe expression")
        # compile & eval
        code = compile(tree, "<expr>", "eval")
        return eval(code, {"__builtins__": {}}, local)

# example_configs.py
# You could source these from JSON or YAML in a real system

configs = {
  # 1) Deal flat damage to target
  "deal_damage": {
    "name":"deal_damage",
    "steps": [
      {"action":"damage", "target":"target", "amount":"config.amount"}
    ]
  },

  # 2) Heal actor
  "heal_self": {
    "name":"heal_self",
    "steps":[
      {"action":"heal", "target":"actor", "amount":"config.amount"}
    ]
  },

  # 3) Heal target
  "heal_target": {
    "name":"heal_target",
    "steps":[
      {"action":"heal", "target":"target", "amount":"config.amount"}
    ]
  },

  # 4) Damage target by portion of target.hp
  "damage_pct_target_hp": {
    "name":"damage_pct_target_hp",
    "steps":[
      {"action":"damage", "target":"target", "amount":"config.pct * target.hp"}
    ]
  },

  # 5) Damage target by portion of actor.hp AND self‐damage
  "suicide_strike": {
    "name":"suicide_strike",
    "steps":[
      {"action":"damage", "target":"target", "amount":"config.pct * actor.hp"},
      {"action":"damage", "target":"actor", "amount":"config.self_pct * actor.hp"},
    ]
  },

  # 6) Life‐leech: damage then heal actor by some fraction of damage done
  "life_leech": {
    "name":"life_leech",
    "steps":[
      {"action":"damage", "target":"target", "amount":"config.pct * actor.damage"},
      {"action":"heal",   "target":"actor",  "amount":"config.leech * last"},
    ]
  },
}

# test.py
if __name__=="__main__":
    from character import Character
    from action import Action
    from example_configs import configs

    hero = Character(dict(name="Hero", hp=100, damage=20))
    enemy= Character(dict(name="Goblin", hp= 50, damage= 5))

    # pick an action
    cfg = configs["life_leech"]
    act = Action(cfg)

    print(hero, enemy)
    # execute with whatever parameters we like
    act.execute(hero, enemy, pct=1.5, leech=0.5)
    print("after life_leech:", hero, enemy)

    # try a flat heal
    heal = Action(configs["heal_self"])
    heal.execute(hero, enemy, amount=30)
    print("after heal_self:", hero, enemy)
```

Explanation
----------
1.  All actions are just lists of small steps, driven entirely by data (JSON/YAML).  
2.  Each `amount` is a Python‐style expression that can refer to  
      - `actor` or `target` (their `.hp`, `.damage`, or any other attribute you add)  
      - `config` (any parameters you pass in at runtime)  
      - `last` (the numeric result of the previous step)  
3.  We use `ast.parse` + a quick walker to ban any unsafe nodes (calls, imports, attributes, etc.), compile and `eval` in a sandboxed namespace.  
4.  Adding new behaviors (burn, buff, shield, stat‐up, run‐away, whatever) is just a matter of:  
      a.  add a new `"action": "burn"` step handler in `execute`,  
      b.  add data for it in your JSON/YAML.  

This gives you a very small DSL that can express all of your examples (and infinite more) without writing a dozen specialized classes.

Here’s a minimal end-to-end example of how you can:

 1. Define a Pinia “session” store  
 2. Call `/get_session` with Vue-Query  
 3. “select” just the bits you care about  
 4. Push those bits into your Pinia store in onSuccess  

—---

1) Define your Pinia store (e.g. stores/session.js)  
```js
import { defineStore } from 'pinia'

export const useSessionStore = defineStore('session', {
  state: () => ({
    userId: null,
    userName: null,
    token: null,
  }),
  actions: {
    setSession(payload) {
      this.userId   = payload.userId
      this.userName = payload.userName
      this.token    = payload.token
    },
  },
})
```

2) Create a composable (or call this in a component)  
```js
// useSessionQuery.js
import { useQuery } from '@tanstack/vue-query'
import { useSessionStore } from '@/stores/session'

/**
 * Fetch the full session object from your back-end.
 * @returns Promise<Object>
 */
function fetchSession() {
  return fetch('/get_session')
    .then(res => {
      if (!res.ok) throw new Error('Network error')
      return res.json()
    })
}

/**
 * A composable that:
 *  • fetches /get_session
 *  • plucks only the fields we actually want
 *  • writes them into Pinia on success
 */
export function useSessionQuery() {
  const sessionStore = useSessionStore()

  return useQuery(
    ['session'],          // query key
    fetchSession,         // how to fetch it
    {
      // select: runs on the raw response,
      // returns only the bits we care about
      select: (fullSession) => ({
        userId:   fullSession.user?.id ?? null,
        userName: fullSession.user?.name ?? 'Anonymous',
        token:    fullSession.token,
      }),

      // onSuccess: now we can take that “selected” payload
      // and write it into our Pinia store
      onSuccess: (selectedSession) => {
        sessionStore.setSession(selectedSession)
      },

      // optional: stale time, retry logic, etc.
      staleTime: 1000 * 60 * 5,  // 5m
      retry:     1,
    }
  )
}
```

3) Use it in a component  
```html
<script setup>
import { useSessionQuery } from '@/composables/useSessionQuery'
import { storeToRefs }   from 'pinia'
import { useSessionStore }from '@/stores/session'

const { data: sessionData, isLoading, isError } = useSessionQuery()
const sessionStore = useSessionStore()
const { userId, userName, token } = storeToRefs(sessionStore)
</script>

<template>
  <div v-if="isLoading">loading…</div>
  <div v-else-if="isError">failed to load session</div>
  <div v-else>
    <p>Queried session.userId: {{ sessionData?.userId }}</p>
    <p>Pinia session.userName: {{ userName }}</p>
    <p>Pinia session.token: {{ token }}</p>
  </div>
</template>
```

—---

Explanation of the key bits:

• useQuery’s `select` option  
  Transforms the raw server response into *exactly* the shape you want to work with.

• useQuery’s `onSuccess` option  
  Fires *after* the data has been fetched & selected, allowing you to dispatch that data into your Pinia store.

• You can still access the raw full payload as `query.data` if you need it—but for most of your UI logic you’ll be using either the “selected” data or your Pinia store directly.

