In SAS there are several ways to drop a variable when you read in your source data.  The simplest is to use a DROP= data‐set option.  For example, you can do any of these:

1) drop in the SET statement  
```sas
data vertical3;
  set vertical2(drop=A);
  format Treatment $Drug. 
         Effectiveness $Effective. 
         Sex $Sex.;
run;
```

2) drop in the DATA statement  
```sas
data vertical3(drop=A);
  set vertical2;
  format Treatment $Drug. 
         Effectiveness $Effective. 
         Sex $Sex.;
run;
```

3) use a DROP statement in the data step  
```sas
data vertical3;
  set vertical2;
  drop A;
  format Treatment $Drug. 
         Effectiveness $Effective. 
         Sex $Sex.;
run;
```

All three of these will create vertical3 without variable A.

Here’s a minimal iMessage‐extension in Swift that, when loaded, will show two buttons side by side in your Messages “keyboard” (that is, in your MSMessagesAppViewController’s view).  

1. In Xcode create a new “iMessage App” target (File → New → Target → iOS → Application Extension → iMessage Extension).  
2. In the generated MessagesViewController.swift replace its contents with the code below.  This example lays out two system buttons (“Button 1” and “Button 2”) in the center of the view, wired up to print to the console when tapped.

```swift
import UIKit
import Messages

class MessagesViewController: MSMessagesAppViewController {

    // MARK: – View Lifecycle

    override func viewDidLoad() {
        super.viewDidLoad()
        setupButtons()
    }

    // If you want to support both compact & expanded modes,
    // override willTransition(to:) / didTransition(to:) to
    // adjust your layout.
    //
    // e.g.
    //
    // override func willTransition(
    //   to presentationStyle: MSMessagesAppPresentationStyle
    // ) {
    //   super.willTransition(to: presentationStyle)
    //   // tweak your button sizes or hide/show here
    // }

    // MARK: – Button Setup

    private func setupButtons() {
        // Create the buttons
        let button1 = makeButton(title: "Button 1", action: #selector(button1Tapped))
        let button2 = makeButton(title: "Button 2", action: #selector(button2Tapped))

        // Add to view
        [button1, button2].forEach {
            view.addSubview($0)
        }

        // Layout with Auto Layout
        NSLayoutConstraint.activate([
            // button1 at left, centered vertically
            button1.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 20),
            button1.centerYAnchor.constraint(equalTo: view.centerYAnchor),

            // button2 at right, centered vertically
            button2.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -20),
            button2.centerYAnchor.constraint(equalTo: view.centerYAnchor),
        ])
    }

    private func makeButton(title: String, action: Selector) -> UIButton {
        let btn = UIButton(type: .system)
        btn.translatesAutoresizingMaskIntoConstraints = false
        btn.setTitle(title, for: .normal)
        btn.titleLabel?.font = UIFont.systemFont(ofSize: 16, weight: .medium)
        btn.addTarget(self, action: action, for: .touchUpInside)
        return btn
    }

    // MARK: – Button Actions

    @objc private func button1Tapped() {
        print("Button 1 tapped")
        // e.g. compose and insert an MSMessage into the conversation…
    }

    @objc private func button2Tapped() {
        print("Button 2 tapped")
        // e.g. do something else
    }

    // MARK: – Conversation Handling

    override func didReceive(_ message: MSMessage, conversation: MSConversation) {
        // Called when the extension receives a message.
    }

    override func didStartSending(_ message: MSMessage, conversation: MSConversation) { }
    override func didCancelSending(_ message: MSMessage, conversation: MSConversation) { }

    override func willTransition(to presentationStyle: MSMessagesAppPresentationStyle) {
        super.willTransition(to: presentationStyle)
        // Adjust your layout if you support .compact vs .expanded
    }

    override func didTransition(to presentationStyle: MSMessagesAppPresentationStyle) {
        super.didTransition(to: presentationStyle)
    }
}
```

Notes:

• By default the Messages extension will start in compact mode (height ~ 216 pt). If you want more room you can request `.expanded` by calling  
```swift
requestPresentationStyle(.expanded)
```  
for example when the user taps one of your buttons.  

• You can also build your UI in Interface Builder. Just hook up two UIButton outlets in your storyboard’s MessagesViewController scene and position them however you like.  

That’s all it takes to get two tappable buttons showing up in your iMessage extension’s keyboard view!

Here’s a one-liner (well… a few lines) you can paste into your DevTools console to fetch any URL (assuming CORS allows it) and trigger a “Save as…” dialog for its contents:

1. Copy/paste into your console  
```js
;(async () => {
  // 1. change this to whatever URL you want to download
  const url = 'https://example.com/some/page-or-file.html';   

  // 2. fetch it
  const resp = await fetch(url);
  if (!resp.ok) throw new Error(`HTTP ${resp.status}`);

  // 3. decide if you want raw text or a blob:
  //    – for an HTML page: use .text(); for binaries (pdf/jpg/zip/etc) use .blob()
  const data = await resp.text();           // or resp.blob()

  // 4. wrap in a Blob
  const blob = new Blob(
    [data],
    { type: resp.headers.get('Content-Type') || 'application/octet-stream' }
  );

  // 5. make a download link and click it
  const dlUrl = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = dlUrl;
  // give it a filename—change as you like
  a.download = url.split('/').pop() || 'download';
  document.body.append(a);
  a.click();

  // 6. clean up
  setTimeout(() => {
    URL.revokeObjectURL(dlUrl);
    a.remove();
  }, 100);
})();
```

Explanation of the steps:

1. **fetch(url)**  
   Downloads the resource. If it’s a text-based file (HTML, JSON, CSS…) use `resp.text()`; if it’s binary (images, zip, pdf…) use `resp.blob()`.
2. **new Blob([...], {type: …})**  
   Wraps the response in a Blob so the browser knows how to handle it.
3. **URL.createObjectURL(blob)**  
   Creates a temporary blob URL.
4. **\<a download> + a.click()**  
   Tells the browser “save this URL as a file” instead of navigating to it.
5. **Cleanup**  
   Revoke the object URL and remove the anchor after a short timeout.

That’s it—paste, edit the `url` and (optionally) `download` filename, and you’ll get a Save dialog for whatever resource you fetched.

Below is a minimal Rust program that

  1. takes a path to a text file on its command-line,
  2. reads all lines (one URL per line),
  3. classifies each line as a YouTube URL or “other,”
  4. invokes `yt-dlp <youtube_url>` on each YouTube URL, and
  5. appends all the non-YouTube URLs to a file called `others.txt` in the current directory.

You’ll need to have `yt-dlp` installed and in your `$PATH`.

---

Cargo.toml:

```toml
[package]
name = url_separator
version = "0.1.0"
edition = "2021"

[dependencies]
regex = "1.7"
```

src/main.rs:

```rust
use regex::Regex;
use std::env;
use std::fs::{File, OpenOptions};
use std::io::{self, BufRead, BufReader, Write};
use std::process::Command;

fn is_youtube_url(url: &str) -> bool {
    // very simple heuristic; tweak to taste
    // matches https://www.youtube.com/... or https://youtu.be/...
    lazy_static::lazy_static! {
        static ref YT_RE: Regex = Regex::new(
            r"(?xi)^https?://(www\.)?(youtube\.com/watch|youtu\.be/)"
        ).unwrap();
    }
    YT_RE.is_match(url)
}

fn main() -> io::Result<()> {
    // 1) grab the input-file path from args
    let mut args = env::args().skip(1);
    let input_path = match args.next() {
        Some(p) => p,
        None => {
            eprintln!("Usage: url_separator <path_to_urls.txt>");
            std::process::exit(1);
        }
    };

    // 2) open the file for reading
    let file = File::open(&input_path)?;
    let reader = BufReader::new(file);

    // 3) open (or create) the others.txt for appending
    let mut others_file = OpenOptions::new()
        .append(true)
        .create(true)
        .open("others.txt")?;

    // 4) process each line
    for line in reader.lines() {
        let url = line?;
        let url = url.trim();
        if url.is_empty() {
            continue;
        }

        if is_youtube_url(url) {
            println!("Downloading YouTube URL: {}", url);
            // call yt-dlp
            let status = Command::new("yt-dlp")
                .arg(url)
                .status()
                .expect("failed to spawn yt-dlp");

            if !status.success() {
                eprintln!("yt-dlp failed on {} (exit code {:?})", url, status.code());
            }
        } else {
            println!("Other URL, saving to others.txt: {}", url);
            writeln!(others_file, "{}", url)?;
        }
    }

    Ok(())
}
```

Explanation of the key parts:

* We use the `regex` crate to detect YouTube URLs.  
* We read the input file line by line using `BufReader`.  
* For each non-empty line we either  
  – spawn `yt-dlp <url>` if it matches YouTube, or  
  – append it to `others.txt` otherwise.  

To run:

1. `cargo build --release`  
2. `./target/release/url_separator path/to/urls.txt`  

After it runs, you’ll have downloaded all matching YouTube videos into your working directory (or wherever `yt-dlp` defaults), and any non-YouTube URLs will be listed in `others.txt`.

Here’s a minimal Console‐app example using `HttpClient` and attaching a client certificate from a .pfx file. You can easily adapt it to load the cert from the Windows Certificate Store instead.

```csharp
using System;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;
using System.Text;
using System.Threading.Tasks;

namespace PostWithClientCert
{
    class Program
    {
        static async Task Main(string[] args)
        {
            // 1) Load your client certificate (.pfx) from disk
            //    You can also load from the Windows cert store instead—see notes below.
            string certPath = "path/to/your/clientcert.pfx";
            string certPassword = "pfxPassword";

            var clientCertificate = new X509Certificate2(certPath, certPassword);

            // 2) Create an HttpClientHandler and attach the client certificate
            var handler = new HttpClientHandler();
            handler.ClientCertificates.Add(clientCertificate);
            // (Optional) If the server certificate is self-signed or untrusted, you
            // can skip validation for testing ONLY:
            // handler.ServerCertificateCustomValidationCallback = HttpClientHandler.DangerousAcceptAnyServerCertificateValidator;

            // 3) Create HttpClient using that handler
            using var client = new HttpClient(handler);

            // 4) Prepare your POST content
            string url = "https://your-api-endpoint.example.com/api/foo";
            string jsonPayload = @"{ ""name"": ""Alice"", ""score"": 42 }";
            using var content = new StringContent(jsonPayload, Encoding.UTF8, "application/json");

            try
            {
                // 5) Send the POST
                HttpResponseMessage response = await client.PostAsync(url, content);

                // 6) Read and display the result
                string body = await response.Content.ReadAsStringAsync();
                Console.WriteLine($"Status: {(int)response.StatusCode} {response.ReasonPhrase}");
                Console.WriteLine("Response body:");
                Console.WriteLine(body);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Request failed:");
                Console.WriteLine(ex);
            }
        }
    }
}
```

Notes & alternatives:

1. Loading from Windows Certificate Store  
   ```csharp
   var store = new X509Store(StoreName.My, StoreLocation.CurrentUser);
   store.Open(OpenFlags.ReadOnly);
   // Find by thumbprint (no spaces, uppercase)
   var found = store.Certificates.Find(
       X509FindType.FindByThumbprint,
       "‎YOURCERTTHUMBPRINTHERE",
       validOnly: false);
   if (found.Count > 0)
       handler.ClientCertificates.Add(found[0]);
   store.Close();
   ```

2. Target framework:  
   - .NET Core / .NET 5+ / .NET 6+: sample above works as‐is.  
   - .NET Framework: same code applies.

3. TLS Versions:  
   If your endpoint requires TLS1.2+, you can enforce it (mostly for old .NET Framework builds)  
   ```csharp
   System.Net.ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
   ```

That’s it—when you run the program it will send a POST and use your client cert in the TLS handshake.

Here’s a small reusable method in C# that will pull out all “#hashtags” from any given string. It uses a regular expression to find words that begin with `#` and returns them (without the `#`) as a `List<string>`:

```csharp
using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public static class HashtagExtractor
{
    /// <summary>
    /// Extracts all hashtags from the input text.
    /// A hashtag is defined here as a ‘#’ followed by one or more
    /// letters, digits or underscores.
    /// </summary>
    /// <param name="text">Input string to search.</param>
    /// <returns>
    /// A list of distinct hashtags (without the leading ‘#’),
    /// in the order they appear.
    /// </returns>
    public static List<string> ExtractHashtags(string text)
    {
        if (string.IsNullOrEmpty(text))
            return new List<string>();

        // Pattern: 
        // (?<=^|\s)   # positive lookbehind for start-of-string or whitespace
        // #           # literal hash
        // ([\p{L}\p{N}_]+)  # capture one or more letters, numbers or underscore
        //
        string pattern = @"(?<=^|\s)#([\p{L}\p{N}_]+)";
        var matches = Regex.Matches(text, pattern);

        var hashtags = new List<string>(matches.Count);
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (Match m in matches)
        {
            string tag = m.Groups[1].Value;
            if (seen.Add(tag)) // avoid duplicates
                hashtags.Add(tag);
        }

        return hashtags;
    }
}

// Example usage:
class Program
{
    static void Main()
    {
        string input = "Loving the new #CSharp8 features! #dotnet #CSharp8 #100DaysOfCode";
        List<string> tags = HashtagExtractor.ExtractHashtags(input);

        Console.WriteLine("Found hashtags:");
        foreach (var t in tags)
            Console.WriteLine(t);
    }
}
```

Explanation of the key parts:

1. Regex pattern `(?<=^|\s)#([\p{L}\p{N}_]+)`  
   - `(?<=^|\s)` ensures the `#` is at the start of the string or preceded by whitespace so we don’t pick up things like `email@domain.com`.  
   - `#` matches the literal hash.  
   - `([\p{L}\p{N}_]+)` captures one or more Unicode letters (`\p{L}`), digits (`\p{N}`), or underscores.

2. We iterate over `Regex.Matches`, pull out `Group[1]` (the text after `#`), and use a `HashSet` to skip duplicates if you want uniqueness.

3. If you’d prefer to keep the leading `#` in the results, just use `m.Value` instead of `m.Groups[1].Value`.

Feel free to tweak the character class (`[\p{L}\p{N}_]`) if you want to allow other characters (e.g. hyphens) in your hashtags.

Here’s a very straightforward way to wire up that “Add User” button so that it reads the user-name from your text input and then POSTs to:

  http://localhost:5000/api/users/{username}/devices/{user_key}

We’ll:

  1. Add a hidden field (or data-attribute) to carry the full RFID key  
  2. Give the button an id so we can bind to it  
  3. Write a tiny bit of vanilla JS (using fetch)  

— HTML changes —

```html
<div class="card-body">
  <h5 class="card-title">Add last used RFID card as new user</h5>
  <p class="card-text">
    Card:
    <strong>
      {{ latest_key[:8] + "..." + latest_key[-8:] }}
    </strong>
    was triggered at:
    <strong>20:57AM</strong>
  </p>

  <!-- hidden store of the full key -->
  <input type="hidden" id="user_key" value="{{ latest_key }}">

  <div class="input-group mb-3">
    <!-- add an id so we can grab it in JS -->
    <button class="btn btn-primary" id="add-user-btn" type="button">
      <i class="bi bi-person-add"></i> Add User
    </button>
    <input type="text" class="form-control" id="user_name" placeholder="User Name">
  </div>
</div>
```

— JavaScript —

Place this at the bottom of your page (just before the closing `</body>`), or wrap it in a DOM-ready handler if you like.

```html
<script>
  document.getElementById('add-user-btn')
    .addEventListener('click', function(e) {
      e.preventDefault();

      // 1) grab the user name
      const nameInput = document.getElementById('user_name');
      const userName  = nameInput.value.trim();
      if (!userName) {
        alert('Please enter a user name.');
        nameInput.focus();
        return;
      }

      // 2) grab the key
      const userKey = document.getElementById('user_key').value;
      if (!userKey) {
        console.error('No user key found!');
        return;
      }

      // 3) build the URL
      const url = `http://localhost:5000/api/users/${encodeURIComponent(userName)}/devices/${encodeURIComponent(userKey)}`;

      // 4) POST
      fetch(url, {
        method: 'POST',
      })
      .then(response => {
        if (!response.ok) {
          return response.text().then(txt => {
            throw new Error(txt || response.statusText);
          });
        }
        return response.json();
      })
      .then(json => {
        // success!
        alert(`User “${userName}” added with key ${userKey}`);
        // TODO: you might want to re-load your table here
      })
      .catch(err => {
        console.error(err);
        alert('Error adding user: ' + err.message);
      });
  });
</script>
```

That’s it.  

If you prefer jQuery:

```js
$('#add-user-btn').click(function(){
  var userName = $('#user_name').val().trim();
  var userKey  = $('#user_key').val();

  if(!userName) { alert('enter name'); return; }

  var url = '/api/users/'+ encodeURIComponent(userName) +
            '/devices/'+ encodeURIComponent(userKey);

  $.post(url)
    .done(function(data){
      alert('OK');
    })
    .fail(function(xhr){
      alert('Error: '+ xhr.responseText);
    });
});
```

Either approach will fire the correct POST for you whenever the button is clicked.

